  more('9-sci', 'Chemistry of life', [['The four main types of biological molecules are carbohydrates, lipids, proteins and…', 'Nucleic acids', 'Minerals', 'Salts', 'Metals'], ['Which molecule stores genetic information?', 'DNA', 'Glucose', 'Fat', 'Starch'], ['Proteins are made of…', 'Amino acids', 'Fatty acids', 'Sugars', 'Nucleotides'], ['The main element in all organic molecules is…', 'Carbon', 'Iron', 'Gold', 'Neon'], ['Water is important for life partly because it…', 'Dissolves many substances', 'Is a solid at room temperature', 'Has no polarity', 'Never changes temperature']]);
  more('9-sci', 'Cell structure and transport', [['Which organelle makes energy (ATP) through respiration?', 'Mitochondrion', 'Ribosome', 'Golgi apparatus', 'Vacuole'], ['Plant cells have ___ that animal cells lack.', 'Cell walls and chloroplasts', 'Mitochondria', 'Ribosomes', 'Cell membranes'], ['Diffusion moves molecules from…', 'High to low concentration', 'Low to high concentration', 'Nowhere', 'Only with energy'], ['Osmosis is the diffusion of…', 'Water', 'Oxygen only', 'Proteins', 'DNA'], ['Prokaryotic cells lack a…', 'Nucleus', 'Cell membrane', 'Ribosome', 'Cytoplasm']]);
  more('9-sci', 'DNA, genes and heredity', [['DNA\'s shape is a…', 'Double helix', 'Single circle', 'Square', 'Triple spiral'], ['Adenine pairs with…', 'Thymine', 'Cytosine', 'Guanine', 'Uracil'], ['A gene is…', 'A section of DNA that codes for a trait or protein', 'A whole cell', 'A type of sugar', 'An organ'], ['Humans have how many chromosomes in most body cells?', '46', '23', '12', '92'], ['A mutation is…', 'A change in the DNA sequence', 'A new cell', 'A type of protein', 'Always harmful']]);
  more('9-sci', 'Evolution', [['Structures with the same origin but different functions (a whale flipper and a human arm) are…', 'Homologous structures', 'Analogous structures', 'Vestigial structures', 'Fossils'], ['Natural selection acts on…', 'Variation in traits', 'Identical individuals', 'Rocks', 'Only plants'], ['The fossil record shows…', 'Life has changed over time', 'Life never changes', 'Only modern animals', 'Nothing'], ['Fitness in evolution means…', 'Ability to survive and reproduce', 'Physical strength only', 'Speed', 'Size'], ['DNA comparisons between species show…', 'How closely related they are', 'Their favorite foods', 'Their exact age', 'Their color']]);
