  more('9-sci', 'Homeostasis', [['Homeostasis is…', 'Keeping stable internal conditions', 'Growing larger', 'Making new species', 'Losing water'], ['Sweating helps the body…', 'Cool down', 'Warm up', 'Grow', 'Digest'], ['Insulin helps control blood…', 'Sugar', 'Pressure only', 'Cells', 'Oxygen'], ['A negative feedback loop…', 'Reverses a change to restore balance', 'Increases the change', 'Has no effect', 'Only happens in plants'], ['Shivering is a response to…', 'Low body temperature', 'High body temperature', 'Hunger', 'Thirst']]);
