  more('9-sci', 'Taxonomy and the tree of life', [['Who created the modern system of naming organisms?', 'Carl Linnaeus', 'Charles Darwin', 'Gregor Mendel', 'Louis Pasteur'], ['A scientific name has two parts: genus and…', 'Species', 'Kingdom', 'Family', 'Order'], ['The three domains of life are Bacteria, Archaea and…', 'Eukarya', 'Plantae', 'Animalia', 'Fungi'], ['Mushrooms belong to the kingdom…', 'Fungi', 'Plantae', 'Animalia', 'Protista'], ['Which level is most specific?', 'Species', 'Kingdom', 'Phylum', 'Class']]);
  add('9-sci', [
    { t: 'Biology lab skills and data', l: ['Every experiment has an independent variable (changed), a dependent variable (measured) and controls (kept the same).', 'Use the metric system and the right tools: graduated cylinder (volume), balance (mass), microscope (magnification).', 'Present data in tables and graphs; calculate averages from repeated trials.', 'Conclusions must be supported by data, and lab safety comes first: goggles, no eating, report spills.'], try: 'Design an experiment testing whether temperature affects how fast yeast makes bubbles.',
      q: [['Which tool measures liquid volume most precisely?', 'Graduated cylinder', 'Beaker', 'Ruler', 'Thermometer'], ['A microscope with a 10× eyepiece and a 40× objective magnifies…', '400×', '50×', '4×', '30×'], ['Why run multiple trials?', 'To make results more reliable', 'To change the variable', 'To save time', 'To skip the control'], ['A control group…', 'Does not receive the treatment', 'Receives double the treatment', 'Is the measured result', 'Is optional'], ['Testing if fertilizer amount affects growth, the dependent variable is…', 'Plant growth', 'Fertilizer amount', 'Pot size', 'Water amount'], ['Which is a lab safety rule?', 'Wear goggles when using chemicals', 'Taste unknown substances', 'Leave spills alone', 'Eat at the lab bench'], ['Trials gave 4, 6 and 8 cm. The mean is…', '6 cm', '18 cm', '8 cm', '4 cm'], ['A conclusion should be…', 'Supported by the data', 'Decided before the experiment', 'Based on opinion', 'As long as possible']] },
    { t: 'Enzymes', l: ['Enzymes are proteins that speed up chemical reactions in cells (they are catalysts).', 'Each enzyme has an active site that fits a specific substrate, like a lock and key.', 'Temperature and pH affect enzymes; too much heat denatures them (changes their shape).', 'Enzymes are not used up in the reaction.'], try: 'Put fresh and boiled pineapple in gelatin. Which one stops it from setting? Why?',
      q: [['Enzymes are mostly made of…', 'Proteins', 'Lipids', 'Sugars', 'Minerals'], ['Enzymes speed up reactions by…', 'Lowering activation energy', 'Raising temperature', 'Being used up', 'Adding water'], ['The molecule an enzyme acts on is the…', 'Substrate', 'Product', 'Active site', 'Catalyst'], ['When an enzyme denatures, it…', 'Loses its shape and function', 'Works faster forever', 'Becomes DNA', 'Multiplies'], ['Which can denature enzymes?', 'Very high temperature', 'Room temperature', 'Gentle light', 'Sound'], ['Are enzymes used up in reactions?', 'No, they can be reused', 'Yes, always', 'Only at night', 'Only in plants'], ['The lock-and-key model explains why enzymes are…', 'Specific to certain substrates', 'Random', 'Made of sugar', 'Always the same shape as DNA'], ['Most human enzymes work best near…', 'Body temperature (37°C)', '0°C', '100°C', '200°C']] },
    { t: 'Photosynthesis and cellular respiration', l: ['Photosynthesis (in chloroplasts): carbon dioxide + water + light energy → glucose + oxygen.', 'Cellular respiration (in mitochondria): glucose + oxygen → carbon dioxide + water + ATP energy.', 'The two processes are near opposites and cycle carbon and oxygen.', 'Without oxygen, some cells use fermentation, which makes much less ATP.'], try: 'Put a water plant in sunlight and watch for oxygen bubbles. Try it in shade.',
      q: [['Photosynthesis takes place in the…', 'Chloroplasts', 'Mitochondria', 'Nucleus', 'Ribosomes'], ['The main product of photosynthesis that stores energy is…', 'Glucose', 'Oxygen', 'Carbon dioxide', 'Water'], ['Cellular respiration releases energy as…', 'ATP', 'Glucose', 'Chlorophyll', 'DNA'], ['Which gas do plants release in photosynthesis?', 'Oxygen', 'Carbon dioxide', 'Nitrogen', 'Helium'], ['Cellular respiration occurs mainly in the…', 'Mitochondria', 'Chloroplasts', 'Cell wall', 'Vacuole'], ['Do plant cells perform cellular respiration?', 'Yes, plants respire too', 'No, never', 'Only at night', 'Only roots'], ['Without oxygen, yeast and muscle cells can use…', 'Fermentation', 'Photosynthesis', 'Osmosis', 'Mitosis'], ['Which is a reactant of photosynthesis?', 'Carbon dioxide', 'Glucose', 'Oxygen', 'ATP']] },
    { t: 'Mitosis and meiosis', l: ['Mitosis makes two identical body cells for growth and repair (phases: prophase, metaphase, anaphase, telophase).', 'Meiosis makes four sex cells (gametes) with half the chromosomes.', 'In humans, body cells have 46 chromosomes; gametes have 23.', 'Crossing over and random assortment in meiosis create genetic variation.'], try: 'Model mitosis with pipe cleaners or string as chromosomes.',
      q: [['Mitosis produces…', 'Two identical cells', 'Four different cells', 'One cell', 'Gametes only'], ['Meiosis produces…', 'Four sex cells with half the chromosomes', 'Two identical body cells', 'One large cell', 'Viruses'], ['A human sperm or egg cell has how many chromosomes?', '23', '46', '92', '12'], ['In which phase do chromosomes line up in the middle?', 'Metaphase', 'Prophase', 'Anaphase', 'Telophase'], ['Mitosis is used for…', 'Growth and repair', 'Making eggs and sperm', 'Photosynthesis', 'Digestion'], ['Crossing over during meiosis increases…', 'Genetic variation', 'Cell size', 'Chromosome number', 'Energy'], ['In anaphase, sister chromatids…', 'Separate and move to opposite poles', 'Line up', 'Disappear', 'Join together'], ['Uncontrolled cell division can lead to…', 'Cancer', 'Photosynthesis', 'Meiosis', 'Osmosis']] },
    { t: 'From DNA to protein', l: ['Transcription: in the nucleus, DNA is copied into messenger RNA (mRNA).', 'Translation: at the ribosome, mRNA is read in three-letter codons and tRNA brings amino acids.', 'RNA uses uracil (U) instead of thymine (T).', 'The order of amino acids decides a protein\'s shape and job, so a mutation can change a protein.'], try: 'Transcribe the DNA strand TACGGA into mRNA (answer: AUGCCU).',
      q: [['Copying DNA into mRNA is called…', 'Transcription', 'Translation', 'Replication', 'Mutation'], ['Building a protein from mRNA at the ribosome is…', 'Translation', 'Transcription', 'Meiosis', 'Osmosis'], ['RNA uses which base instead of thymine?', 'Uracil', 'Adenine', 'Guanine', 'Cytosine'], ['A codon is…', 'Three mRNA bases that code for an amino acid', 'A whole gene', 'A protein', 'A chromosome'], ['DNA strand TAC is transcribed into mRNA as…', 'AUG', 'ATG', 'TAC', 'UAC'], ['Which molecule carries amino acids to the ribosome?', 'tRNA', 'mRNA', 'DNA', 'ATP'], ['Proteins are built from…', 'Amino acids', 'Nucleotides', 'Fatty acids', 'Glucose'], ['A mutation that changes one base can…', 'Change the protein made', 'Never matter', 'Turn DNA into RNA', 'Stop all cells']] },
    { t: 'Patterns of inheritance', l: ['Mendel discovered dominant and recessive alleles using pea plants.', 'Punnett squares predict offspring ratios; a heterozygous cross (Aa × Aa) gives 3:1 phenotypes.', 'Incomplete dominance blends traits (red × white = pink); codominance shows both (AB blood type).', 'Sex-linked traits, like color blindness, are carried on the X chromosome and show more often in males.'], try: 'Make a Punnett square for two parents with type AO and BO blood. What types could their children have?',
      q: [['Who is known as the father of genetics?', 'Gregor Mendel', 'Charles Darwin', 'Watson and Crick', 'Linnaeus'], ['Aa × Aa produces a phenotype ratio of…', '3 dominant : 1 recessive', '1 : 1', 'All dominant', '1 : 2'], ['Red × white flowers producing pink flowers shows…', 'Incomplete dominance', 'Codominance', 'Complete dominance', 'Mutation'], ['Type AB blood is an example of…', 'Codominance', 'Incomplete dominance', 'A recessive trait', 'A sex-linked trait'], ['Color blindness is more common in males because it is…', 'X-linked recessive', 'Y-linked dominant', 'Codominant', 'Caused by diet'], ['A heterozygous genotype is…', 'Aa', 'AA', 'aa', 'A'], ['Aa × aa: what fraction of offspring show the recessive trait?', '1/2', '1/4', '3/4', '0'], ['Homozygous recessive is written as…', 'aa', 'Aa', 'AA', 'Ab']] },
    { t: 'Populations and carrying capacity', l: ['A population is all members of one species in an area.', 'Populations grow exponentially when resources are unlimited (J-curve).', 'Limited resources cause logistic growth that levels off at the carrying capacity (S-curve).', 'Limiting factors: food, space, predators, disease; density-dependent factors grow stronger as a population gets crowded.'], try: 'Graph a deer population that grows fast, then levels off. Label the carrying capacity.',
      q: [['Carrying capacity is…', 'The largest population an environment can support', 'The number of babies born', 'The size of a habitat', 'The speed of growth'], ['Unlimited resources produce which growth curve?', 'J-shaped (exponential)', 'S-shaped (logistic)', 'Flat line', 'Downward line'], ['Logistic growth levels off because of…', 'Limiting factors', 'Unlimited food', 'No predators', 'Sunlight'], ['Which is a density-dependent limiting factor?', 'Disease spreading in a crowded population', 'A volcano', 'A hurricane', 'A drought from far away'], ['If wolves are removed, a deer population will likely first…', 'Increase', 'Decrease', 'Stay exactly the same', 'Disappear'], ['A population near carrying capacity has…', 'A birth rate about equal to its death rate', 'Rapid growth', 'No deaths', 'No births'], ['Which is a limiting factor?', 'Food supply', 'The color of the sky', 'Time of day', 'Name of the species'], ['An invasive species can harm an ecosystem by…', 'Outcompeting native species', 'Adding diversity always', 'Doing nothing', 'Cooling the climate']] }
  ]);
